ALTER TABLE "organization"."role" DROP CONSTRAINT "role_permissions_check", ADD CONSTRAINT "role_permissions_check" CHECK (jsonb_typeof("permissions") = 'array' and (("scope_kind" = 'organization' and "permissions" <@ '["audit.read","organization.read","organization.update","organization.archive","members.read","members.manage","roles.read","roles.manage","roles.assign","teams.read","teams.manage"]'::jsonb) or ("scope_kind" = 'team' and "permissions" <@ '["team.read","team.update","team.archive","team.members.read","team.members.manage","team.roles.read","team.roles.assign"]'::jsonb)));